//! FORM method reflects known keywords independently of native transport refusal.
use super::*;
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse("<html><body><form id=form action=https://form-method.test/submit><input id=area name=q value=Seed><button id=submit name=go value=sent></button></form><input id=neighbor value=seed></body></html>");d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();let l=crate::navigation::address("https://form-method.test/source",&crate::navigation::Location::home()).unwrap();p.set_location(&l);p.set_resource_base(&l);assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}
#[test]
fn form_method_canonical_once_conversion_known_keywords_and_exact_raw_attribute(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('form'),a=Object.getOwnPropertyDescriptor(HTMLFormElement.prototype,'method');if(!a||!a.enumerable||!a.configurable||a.get.name!=='get method'||a.set.name!=='set method'||a.get.length!==0||a.set.length!==1||Object.hasOwn(x,'method')||x.method!=='get')throw 'canonical';var calls=0;x.method={toString:function(){calls++;return 'PoSt';},valueOf:function(){throw 'wrong hint';}};if(calls!==1||x.method!=='post'||x.getAttributeNS(null,'method')!=='PoSt')throw 'once reflected';x.method='DIALOG';if(x.method!=='dialog')throw 'dialog keyword';x.method=' post ';if(x.method!=='get'||x.getAttributeNS(null,'method')!==' post ')throw 'no trim';x.method='A\ud800Z';if(x.method!=='get'||x.getAttributeNS(null,'method')!=='A\ud800Z')throw 'exact raw';x.method=null;if(x.method!=='get'||x.getAttribute('method')!=='null')throw 'null';x.method=undefined;if(x.method!=='get'||x.getAttribute('method')!=='undefined')throw 'undefined';"#);}
#[test]
fn form_method_inert_exact_namespace_and_independent_copy(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=(new Document()).createElementNS('http://www.w3.org/1999/xhtml','form');x.setAttributeNS('urn:other','method','post');x.setAttributeNS(null,'METHOD','post');if(x.method!=='get')throw 'exact name';x.method='PoSt';var copy=x.cloneNode(false);copy.method='DIALOG';if(x.method!=='post'||copy.method!=='dialog'||x.getAttributeNS(null,'method')!=='PoSt'||copy.getAttributeNS(null,'method')!=='DIALOG')throw 'independent reflection';"#);}
#[test]
fn form_method_drives_existing_native_get_post_and_dialog_refusal(){let(mut d,mut f,mut p)=fixture();let owner=(0..d.nodes.len()).find(|&n|d.attr(n,"id")==Some("form")).unwrap();let l=crate::navigation::address("https://form-method.test/source",&crate::navigation::Location::home()).unwrap();for(value,canonical,post)in[("PoSt","post",true),("GET","get",false),(" post ","get",false),("invalid","get",false)]{p.begin_job();run(&mut d,&mut f,&mut p,&format!("var x=document.getElementById('form');x.method='{value}';if(x.method!=='{canonical}')throw 'method';"));let result=f.submit_request(&d,owner,None,&l,&l).unwrap();assert_eq!(matches!(result.request,crate::http::Request::FormPost{..}),post);}p.begin_job();run(&mut d,&mut f,&mut p,"x.method='DIALOG';if(x.method!=='dialog')throw 'dialog reflection';");let before=format!("{:?}",d.nodes);let error=f.submit_request(&d,owner,None,&l,&l).err().unwrap();assert!(error.contains("DIALOG is not implemented"),"{error}");assert_eq!(format!("{:?}",d.nodes),before);}

#[test]
fn form_method_authority_brands_and_abrupt_once_conversion(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('form'),P=HTMLFormElement.prototype,a=Object.getOwnPropertyDescriptor(P,'method'),calls=0;for(var bad of [{},document,document.body,Object.create(P)]){try{a.set.call(bad,{toString:function(){calls++;return 'get';}});throw 'missing brand';}catch(e){if(!(e instanceof TypeError))throw e;}}if(calls)throw 'brand converted';x.method={toString:function(){calls++;x.method='post';return ' EMAIL ';}};if(calls!==1||x.method!=='get')throw 'outer conversion';var marker={};try{x.method={toString:function(){x.setAttribute('data-side','kept');throw marker;}};throw 'missing abrupt';}catch(e){if(e!==marker)throw e;}if(x.method!=='get'||x.getAttribute('data-side')!=='kept')throw 'abrupt state';Object.defineProperty(P,'method',{get:function(){return 'author';},set:function(v){this.setAttribute('data-author',v);},configurable:true});x.method='override';a.set.call(x,'GET');if(x.method!=='author'||a.get.call(x)!=='get')throw 'saved authority';delete P.method;if(x.method!==undefined)throw 'hidden member';Object.defineProperty(P,'method',a);var C=HTMLFormElement;delete window.HTMLFormElement;if(!(x instanceof C)||a.get.call(x)!=='get')throw 'saved constructor';");}
#[test]
fn form_method_saved_child_origin_precedes_conversion_and_recovers(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('form'),frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var a=Object.getOwnPropertyDescriptor(frame.contentWindow.HTMLFormElement.prototype,'method'),calls=0;if(a.get.call(x)!=='get')throw 'same origin';");p.set_location(&crate::navigation::address("https://foreign-form-method.test/",&crate::navigation::Location::home()).unwrap());let before=format!("{:?}",d.nodes);for code in ["a.get.call(x);","a.set.call(x,{toString:function(){calls++;return 'get';}});"]{p.begin_job();let error=p.runtime.execute(code,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(error.contains("origin")||error.contains("Security"),"{error}");assert_eq!(format!("{:?}",d.nodes),before);}p.set_location(&crate::navigation::address("https://form-method.test/source",&crate::navigation::Location::home()).unwrap());p.begin_job();run(&mut d,&mut f,&mut p,"if(calls)throw 'origin converted';a.set.call(x,'GET');if(x.method!=='get')throw 'fresh recovery';");}

#[test]
fn form_method_named_control_precedence_preserves_saved_accessor_authority(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('form'),n=document.getElementById('area'),a=Object.getOwnPropertyDescriptor(HTMLFormElement.prototype,'method');n.setAttribute('name','method');if(x.method!==n)throw 'named control precedence';var calls=0,watch=new MutationObserver(function(){});watch.observe(x,{attributes:true,attributeOldValue:true});a.set.call(x,{toString:function(){calls++;return 'POST';}});var records=watch.takeRecords();if(calls!==1||records.length!==1||records[0].attributeName!=='method'||x.method!==n||a.get.call(x)!=='post'||x.getAttributeNS(null,'method')!=='POST')throw 'saved authority';a.set.call(x,'post\\ud800');if(a.get.call(x)!=='get'||x.getAttributeNS(null,'method')!=='post\\ud800')throw 'named raw setter';a.set.call(x,'POST');n.setAttribute('name','q');if(x.method!=='post')throw 'live named removal';");}
#[test]
fn form_method_resource_refusal_is_atomic_and_fresh_job_recovers(){for getter in [false,true]{for mode in 0..4{let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('form');x.method='post';");let Value::Host(object)=p.runtime.execute("x;",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap()else{panic!("form")};let before=format!("{:?}",d.nodes);let retained=p.state.retained_limit;let string_limit=p.state.limits.host.string_bytes;let capture=(p.state.retained,p.state.dom_commits);p.begin_job();match mode{0=>p.state.copy_work=0,1=>p.state.host_work=0,2 if !getter=>p.state.retained_limit=p.state.retained,2=>p.state.limits.host.string_bytes=1,_=>p.state.execution_deadline=Some(Instant::now())};let mut bridge=Bridge{doc:&mut d,forms:&mut f,state:&mut p.state};let result=if getter{bridge.form_method_get(object).map(|_|())}else{bridge.form_method_set(object,&Value::String("growing-unknown-method-value".into()))};assert!(result.is_err(),"getter {getter} mode {mode}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits),capture);p.state.retained_limit=retained;p.state.limits.host.string_bytes=string_limit;p.state.execution_deadline=None;p.begin_job();run(&mut d,&mut f,&mut p,"x.method='GET';if(x.method!=='get'||document.getElementById('area').value!=='Seed')throw 'fresh recovery';");}}}
#[test]
fn form_method_attribute_writers_observe_raw_values_and_preserve_dirty_editor(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('form'),editor=document.getElementById('area');editor.value='Edited';x.method='get';var attribute=x.getAttributeNodeNS(null,'method'),watch=new MutationObserver(function(){});watch.observe(x,{attributes:true,attributeOldValue:true,attributeFilter:['method']});");let n=*f.controls.keys().find(|n|d.attr(**n,"id")==Some("area")).unwrap();{let e=&mut f.controls.get_mut(&n).unwrap().value;e.cursor=3;e.anchor=1;e.offset=2;}for source in ["x.setAttribute('method','POST');","x.setAttributeNS(null,'method','POST');","attribute.value='POST';","attribute.nodeValue='POST';","attribute.textContent='POST';"]{p.begin_job();run(&mut d,&mut f,&mut p,"x.method='get';watch.takeRecords();");run(&mut d,&mut f,&mut p,source);run(&mut d,&mut f,&mut p,"var records=watch.takeRecords();if(x.method!=='post'||x.getAttributeNodeNS(null,'method')!==attribute||records.length!==1||records[0].oldValue!=='get'||records[0].attributeName!=='method'||editor.value!=='Edited')throw 'attribute observation';");let c=&f.controls[&n];assert_eq!((c.value.cursor,c.value.anchor,c.value.offset,c.dirty_value),(3,1,2,true));}run(&mut d,&mut f,&mut p,r#"var replacement=document.createAttribute('method');replacement.value='post\ud800';x.setAttributeNodeNS(replacement);if(x.method!=='get'||attribute.ownerElement!==null||replacement.ownerElement!==x||replacement.value!=='post\ud800')throw 'raw attribute replacement';"#);}
